fundingProjectionSQL.sql:
SELECT row_to_json(s) FROM (SELECT instrument_id,funding_time,count(*) records,count(distinct funding_rate_ppm) rates,min(sequence) min_sequence,max(sequence) max_sequence FROM funding_rate_ticks WHERE status='FINAL' GROUP BY instrument_id,funding_time ORDER BY funding_time DESC,instrument_id LIMIT 12) s;
SELECT row_to_json(s) FROM (SELECT product_line,count(*) settlements FROM core_funding_settlement_projection GROUP BY product_line) s;
SELECT row_to_json(s) FROM (SELECT product_line,count(*) payments FROM core_funding_payment_projection GROUP BY product_line) s;
SELECT row_to_json(s) FROM (SELECT relname,n_live_tup,n_tup_ins,n_tup_upd,n_dead_tup FROM pg_stat_user_tables WHERE relname LIKE 'core_%projection' ORDER BY relname) s;
SELECT row_to_json(s) FROM (SELECT datname,age(datfrozenxid) xid_age FROM pg_database ORDER BY xid_age DESC) s;
SELECT row_to_json(s) FROM (SELECT version,settings->'funding' funding FROM lifecycle_business_settings WHERE product_line='LINEAR_PERPETUAL') s;
